{"witnessCode": "import { test } from 'node:test'; import assert from 'node:assert/strict'; import normalizeUrl from '../index.js';

test('normalizeUrl adds default protocol to dot-containing custom protocol when defaultProtocol is non‑special', async t => {
  const input = 'example.com:foo';
  const options = { defaultProtocol: 'foo' };
  const expected = 'foo:example.com:foo';
  const actual = normalizeUrl(input, options);
  assert.strictEqual(actual, expected);
});
"}
